globalJavaScript:
// Live utilities using free, key-less public APIs plus a few offline tricks.
// GET() prefers the built-in httpGet if present, otherwise falls back to
// httpRequest so this set works on any build of the patch.
function GET(url){
  if (typeof httpGet === "function"){ return httpGet(url); }
  return httpRequest({ method: "GET", url: url });
}
function jget(url){ return JSON.parse(GET(url)); }
